    "kernel_code": "1: import torch\n2: import triton\n3: import triton.language as tl\n4: \n5: @triton.jit\n6: def _kernel(X, W, O, K: tl.constexpr):\n7:     row = tl.program_id(0)\n8:     j = tl.arange(0, K)\n9:     x = tl.load(X + j)\n10:     w = tl.load(W + row * K + j)\n11:     scale = tl.max(tl.abs(w), 0) / 7.0\n12:     qi = tl.minimum(7.0, tl.maximum(-7.0, tl.floor(w / scale + 0.5)))\n13:     y = tl.sum(x * (qi * scale), 0)\n14:     tl.store(O + row, y)\n15: \n16: def run(x, w):\n17:     m, k = w.shape\n18:     out = torch.empty(m, dtype=torch.float32, device=x.device)\n19:     _kernel[(m,)](x, w, out, k, enable_fp_fusion=False)\n20:     return out\n21: \n22: CONFIG = {'family': 'quantization', 'seed': 1224, 'm': 32, 'k': 256, 'mix': 0.75, 'residual': 1.0}\n23: \n24: def make_inputs(device=\"cuda\"):\n25:     import numpy as np\n26:     cfg = CONFIG\n27:     # CPU NumPy PCG64; all inputs are then rounded once to binary32.\n28:     rng = np.random.Generator(np.random.PCG64(cfg[\"seed\"]))\n29:     def tensor(x):\n30:         return torch.from_numpy(np.asarray(x, dtype=np.float32).copy()).to(device)\n31:     if cfg[\"family\"] == \"attention\":\n32:         n, d = cfg[\"n\"], cfg[\"d\"]\n33:         q = rng.standard_normal(d)\n34:         k = rng.standard_normal((n, d)) * cfg[\"scale\"]\n35:         # Structured value offset controls cancellation in the output.\n36:         v = rng.standard_normal((n, d))\n37:         q32, k32 = q.astype(np.float32), k.astype(np.float32)\n38:         z = k32.astype(np.float64) @ q32.astype(np.float64) / np.sqrt(d)\n39:         p = np.exp(z - z.max()); p /= p.sum()\n40:         v -= cfg[\"center\"] * (p @ v)[None, :]\n41:         return tensor(q32), tensor(k32), tensor(v)\n42:     if cfg[\"family\"] == \"quantization\":\n43:         m, k = cfg[\"m\"], cfg[\"k\"]\n44:         w = rng.standard_normal((m, k)).astype(np.float32)\n45:         x = rng.standard_normal(k)\n46:         # Mix a weight direction with an independently sampled direction.\n47:         direction = w.astype(np.float64).sum(axis=0)\n48:         direction /= np.linalg.norm(direction)\n49:         x /= np.linalg.norm(x)\n50:         x = cfg[\"mix\"] * direction + (1.0 - cfg[\"mix\"]) * x\n51:         wf = w.astype(np.float64)\n52:         scale = np.max(np.abs(wf), axis=1, keepdims=True) / 7.0\n53:         residual = (np.clip(np.floor(wf / scale + 0.5), -7, 7) * scale - wf).sum(axis=0)\n54:         residual /= np.linalg.norm(residual)\n55:         x += cfg[\"residual\"] * residual\n56:         return tensor(x), tensor(w)\n57:     t, d = cfg[\"t\"], cfg[\"d\"]\n58:     a = np.full((t, d), cfg[\"decay\"], dtype=np.float64)\n59:     b = rng.standard_normal((t, d)) * cfg[\"noise\"]\n60:     b += cfg[\"bias\"]\n61:     return tensor(a), tensor(b)",
